    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1, discountPercent: 150 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1, discountPercent: -5 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1, discountPercent: 'invalid' }), { ok: false, error: 'DISCOUNT_INVALID' });
});

